layer.css:
[data-ryt="footer"] { color: #8b8f92; font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 300; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 35%, transparent); text-decoration-thickness: 0.5px; text-underline-offset: 1.6px; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 300; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 35%, transparent); text-decoration-thickness: 0.5px; text-underline-offset: 1.44px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 35%, transparent); text-decoration-thickness: 0.5px; text-underline-offset: 1.6px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 35%, transparent); text-decoration-thickness: 0.5px; text-underline-offset: 1.6px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 300; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 35%, transparent); text-decoration-thickness: 0.5px; text-underline-offset: 1.6px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #d04000; text-decoration-color: rgba(208, 64, 0, 0.35) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #d04000; text-decoration-color: rgba(208, 64, 0, 0.35) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #d04000; text-decoration-color: rgba(208, 64, 0, 0.35) }
[data-ryt="nav"] a:hover { color: #d04000; text-decoration-color: rgba(208, 64, 0, 0.35) }
[data-ryt="brand"]:hover { color: #d04000; text-decoration-color: rgba(208, 64, 0, 0.35); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
